// Package file implements the "file" template-function namespace.
//
// The functions operate on the local filesystem. Paths given to Read, Stat,
// ReadDir, Exists and IsDir are cleaned before use (so a trailing slash on a
// regular file is tolerated), while Walk preserves the root path verbatim in
// its output. Error messages report paths relative to the filesystem root
// (i.e. absolute paths with the leading slash stripped), mirroring the
// observed behaviour of the reference tool.
//
// Write is restricted to files contained within the current working
// directory; attempts to write elsewhere fail.
package file

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"syscall"
)

// NS returns the file namespace: a pointer to a struct whose methods
// implement the namespace's template functions.
func NS() any { return &funcs{} }

type funcs struct{}

// toString converts an arbitrary template value to a string, following the
// reference tool's coercion: nil becomes "nil", byte slices are taken as-is,
// and everything else goes through fmt's %v verb.
func toString(v any) string {
	if v == nil {
		return "nil"
	}
	switch t := v.(type) {
	case string:
		return t
	case []byte:
		return string(t)
	}
	return fmt.Sprintf("%v", v)
}

// displayPath renders p the way the reference tool does in error messages:
// relative paths are resolved against the working directory, the result is
// cleaned, and the leading slash of the absolute path is stripped. The empty
// path is left empty.
func displayPath(p string) string {
	if p == "" {
		return ""
	}
	if !filepath.IsAbs(p) {
		if wd, err := os.Getwd(); err == nil {
			p = filepath.Join(wd, p)
		}
	}
	return strings.TrimPrefix(filepath.Clean(p), "/")
}

// rewriteErr replaces the path carried by a *fs.PathError with its display
// form. Non-PathError values are returned unchanged.
func rewriteErr(err error, p string) error {
	var pe *fs.PathError
	if errors.As(err, &pe) {
		return &fs.PathError{Op: pe.Op, Path: displayPath(p), Err: pe.Err}
	}
	return err
}

// cleanPath converts v to a cleaned filesystem path. The empty string is
// returned as-is so callers can reject it before cleaning would turn it
// into ".".
func cleanPath(v any) string {
	p := toString(v)
	if p == "" {
		return ""
	}
	return filepath.Clean(p)
}

func invalidArgument(op string) error {
	return &fs.PathError{Op: op, Path: "", Err: syscall.EINVAL}
}

// Exists reports whether a file or directory exists at the given path.
func (funcs) Exists(path any) bool {
	p := cleanPath(path)
	if p == "" {
		return false
	}
	_, err := os.Stat(p)
	return err == nil
}

// IsDir reports whether the given path is a directory.
func (funcs) IsDir(path any) bool {
	p := cleanPath(path)
	if p == "" {
		return false
	}
	fi, err := os.Stat(p)
	return err == nil && fi.IsDir()
}

// Read reads a given file as text.
func (funcs) Read(path any) (string, error) {
	p := cleanPath(path)
	if p == "" {
		return "", invalidArgument("readfile")
	}
	fh, err := os.Open(p)
	if err != nil {
		return "", rewriteErr(err, p)
	}
	defer fh.Close()
	b, err := io.ReadAll(fh)
	if err != nil {
		return "", rewriteErr(err, p)
	}
	return string(b), nil
}

// ReadDir reads a directory and lists the names of the files and directories
// contained within, in lexical order.
func (funcs) ReadDir(path any) ([]string, error) {
	p := cleanPath(path)
	if p == "" {
		return nil, invalidArgument("readdir")
	}
	entries, err := os.ReadDir(p)
	if err != nil {
		return nil, rewriteErr(err, p)
	}
	names := make([]string, len(entries))
	for i, e := range entries {
		names[i] = e.Name()
	}
	return names, nil
}

// Stat returns an os.FileInfo describing the named path.
func (funcs) Stat(path any) (os.FileInfo, error) {
	p := cleanPath(path)
	if p == "" {
		return nil, invalidArgument("stat")
	}
	fi, err := os.Stat(p)
	if err != nil {
		return nil, rewriteErr(err, p)
	}
	return fi, nil
}

// Walk recursively walks the file tree rooted at path and returns the paths
// of all files and directories contained within, including the root itself,
// in lexical order. The root path is reported exactly as given. Symbolic
// links are followed for the root only; links encountered below the root are
// listed but not descended into.
func (funcs) Walk(path any) ([]string, error) {
	root := toString(path)
	if root == "" {
		return nil, invalidArgument("stat")
	}
	fi, err := os.Stat(root)
	if err != nil {
		return nil, rewriteErr(err, root)
	}
	out := []string{root}
	if fi.IsDir() {
		if err := walkDir(root, &out); err != nil {
			return nil, err
		}
	}
	return out, nil
}

func walkDir(dir string, out *[]string) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return rewriteErr(err, dir)
	}
	for _, e := range entries {
		p := filepath.Join(dir, e.Name())
		*out = append(*out, p)
		if e.IsDir() {
			if err := walkDir(p, out); err != nil {
				return err
			}
		}
	}
	return nil
}

// Write writes the given data to the given file, overwriting it if it
// exists. The file must be contained within the current working directory.
// Non-existing directories in the output path are created. Byte slices are
// written as-is; any other data is converted to a string first.
func (funcs) Write(path, data any) (string, error) {
	p := toString(path)

	wd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	abs := p
	if !filepath.IsAbs(abs) {
		abs = filepath.Join(wd, abs)
	}
	rel, err := filepath.Rel(wd, abs)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("failed to open %s: path %s not contained by working directory %s (rel: %s)",
			p, p, wd, rel)
	}

	if p == "" {
		return "", fmt.Errorf("failed to stat %s: %w", p, invalidArgument("stat"))
	}
	if _, err := os.Stat(abs); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return "", fmt.Errorf("failed to stat %s: %w", p, rewriteErr(err, p))
	}

	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return "", fmt.Errorf("failed to write %s: %w", p, rewriteErr(err, p))
	}

	var b []byte
	if bb, ok := data.([]byte); ok {
		b = bb
	} else {
		b = []byte(toString(data))
	}
	if err := os.WriteFile(abs, b, 0o644); err != nil {
		return "", fmt.Errorf("failed to write %s: %w", p, rewriteErr(err, p))
	}
	return "", nil
}

