func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"file": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

// renderErr renders tmpl and returns the portion of the execution error
// after "error calling <name>: ", i.e. the error text returned by the
// function itself.
func renderErr(t *testing.T, tmpl, name string) string {
	t.Helper()
	_, err := render(t, tmpl)
	if err == nil {
		t.Fatalf("expected error rendering %q, got none", tmpl)
	}
	needle := "error calling " + name + ": "
	idx := strings.Index(err.Error(), needle)
	if idx < 0 {
		t.Fatalf("error %q does not contain %q", err.Error(), needle)
	}
	return err.Error()[idx+len(needle):]
}

// disp converts an absolute path to the form the reference tool uses in
// error messages (leading slash stripped).
func disp(p string) string {
	return strings.TrimPrefix(filepath.Clean(p), "/")
}

