	//   foo/{a,b,c}   files
	//   foo/d/        directory
	//   foo/sub/{one,two}
	//   foo/link      symlink -> a
	//   dlink         symlink -> foo
	//   broken        symlink -> nonexistent
	//   empty/        empty directory
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(os.WriteFile(filepath.Join(dir, "hi"), []byte("hello world"), 0o644))
	must(os.MkdirAll(filepath.Join(dir, "foo", "sub"), 0o755))
