			continue
		}
		if string(b) != c.content {
			t.Errorf("%s: file content %q, want %q", tmpl, string(b), c.content)
		}
	}

	// map data via template data
	{
		tt, err := template.New("<arg>").Funcs(template.FuncMap{"file": func() any { return NS() }}).Parse(`{{ file.Write "map.txt" .data }}`)
		if err != nil {
