	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "|string" {
		t.Errorf("return value: got %q, want %q", got, "|string")
	}

	// overwrite an existing file, permissions preserved
	{
		target := filepath.Join(root, "over.txt")
		if err := os.WriteFile(target, []byte("old content here"), 0o640); err != nil {
			t.Fatal(err)
		}
		if _, err := render(t, `{{ file.Write "over.txt" "new" }}`); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		b, _ := os.ReadFile(target)
		if string(b) != "new" {
			t.Errorf("overwrite: got %q, want %q", string(b), "new")
		}
		fi, _ := os.Stat(target)
		if fi.Mode().Perm() != 0o640 {
			t.Errorf("overwrite: perm %v changed", fi.Mode().Perm())
		}
	}

	// absolute path inside the working directory is allowed
	abs := filepath.Join(root, "abs.txt")
	if _, err := render(t, `{{ file.Write "`+abs+`" "abs" }}`); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if b, _ := os.ReadFile(abs); string(b) != "abs" {
		t.Errorf("absolute in-cwd write failed")
	}

	// created directories have 0755 and files 0644 (umask permitting)
	fi, err := os.Stat(filepath.Join(root, "sub2", "deep"))
	if err != nil {
		t.Fatal(err)
	}
	if fi.Mode().Perm() != 0o755 {
		t.Errorf("dir perm: got %v, want drwxr-xr-x", fi.Mode().Perm())
	}
	fi, err = os.Stat(filepath.Join(root, "out.txt"))
	if err != nil {
		t.Fatal(err)
	}
	if fi.Mode().Perm() != 0o644 {
		t.Errorf("file perm: got %v, want -rw-r--r--", fi.Mode().Perm())
	}
}

