	errCases := []struct {
		tmpl string
		want string
	}{
		{
			`{{ file.Write "../escape.txt" "bad" }}`,
			"failed to open ../escape.txt: path ../escape.txt not contained by working directory " + root + " (rel: ../escape.txt)",
		},
		{
			`{{ file.Write "/etc/evil.txt" "bad" }}`,
			"failed to open /etc/evil.txt: path /etc/evil.txt not contained by working directory " + root + " (rel: " + mustRel(t, root, "/etc/evil.txt") + ")",
		},
		{
			`{{ file.Write "" "y" }}`,
			"failed to stat : stat : invalid argument",
		},
		{
			`{{ file.Write "hi/x" "y" }}`,
			"failed to stat hi/x: stat " + disp(filepath.Join(root, "hi", "x")) + ": not a directory",
		},
		{
			`{{ file.Write "hi/deep/x" "y" }}`,
			"failed to stat hi/deep/x: stat " + disp(filepath.Join(root, "hi", "deep", "x")) + ": not a directory",
		},
		{
			`{{ file.Write "." "y" }}`,
			"failed to write .: open " + disp(root) + ": is a directory",
		},
		{
			`{{ file.Write "empty/" "x" }}`,
			"failed to write empty/: open " + disp(filepath.Join(root, "empty")) + ": is a directory",
		},
	}
	for _, c := range errCases {
		if got := renderErr(t, c.tmpl, "Write"); got != c.want {
			t.Errorf("%s:\n  got  %q\n  want %q", c.tmpl, got, c.want)
		}
	}

	// nothing must have been written outside
	if _, err := os.Stat(filepath.Join(filepath.Dir(root), "escape.txt")); !os.IsNotExist(err) {
		t.Errorf("escape.txt was written outside the working directory")
	}
}

func mustRel(t *testing.T, base, target string) string {
	t.Helper()
	rel, err := filepath.Rel(base, target)
	if err != nil {
		t.Fatal(err)
	}
	return rel
}

func TestArityErrors(t *testing.T) {
	cases := []struct {
		tmpl string
		want string
	}{
		{`{{ file.Read }}`, "wrong number of args for Read: want 1 got 0"},
		{`{{ file.Read "a" "b" }}`, "wrong number of args for Read: want 1 got 2"},
		{`{{ file.Exists }}`, "wrong number of args for Exists: want 1 got 0"},
		{`{{ file.Write }}`, "wrong number of args for Write: want 2 got 0"},
		{`{{ file.Write "onlyone" }}`, "wrong number of args for Write: want 2 got 1"},
	}
	for _, c := range cases {
		_, err := render(t, c.tmpl)
		if err == nil {
			t.Errorf("%s: expected error, got none", c.tmpl)
			continue
		}
		if !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: error %q does not contain %q", c.tmpl, err.Error(), c.want)
		}
	}
}

